"""Independent verification of synthetic trust generated by the ARM binary."""
from pathlib import Path
import sys, plistlib, json, uuid
from datetime import datetime, timezone
from cryptography import x509
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa, padding
OUT=Path(__file__).resolve().parents[2]/'../build/carplay/ce-phone-pair-test'
if '--output' in sys.argv:
    OUT=Path(sys.argv[sys.argv.index('--output')+1])
if '--prepare' in sys.argv:
    OUT.mkdir(parents=True,exist_ok=True)
    key=rsa.generate_private_key(public_exponent=65537,key_size=2048)
    (OUT/'device-public.pem').write_bytes(key.public_key().public_bytes(serialization.Encoding.PEM,serialization.PublicFormat.PKCS1))
    sys.exit(0)
p=plistlib.loads((OUT/'generated-pair.plist').read_bytes())
wire=plistlib.loads((OUT/'pair-request.plist').read_bytes())
root=x509.load_pem_x509_certificate(p['RootCertificate'])
now=datetime.now(timezone.utc)
for name in ('Root','Host','Device'):
    cert=x509.load_pem_x509_certificate(p[name+'Certificate'])
    root.public_key().verify(cert.signature,cert.tbs_certificate_bytes,padding.PKCS1v15(),cert.signature_hash_algorithm)
    assert cert.signature_hash_algorithm.name=='sha256'
    assert cert.issuer==root.subject
    assert cert.not_valid_before_utc<=now<=cert.not_valid_after_utc
    bc=cert.extensions.get_extension_for_class(x509.BasicConstraints)
    assert bc.critical and bc.value.ca==(name=='Root')
    if name!='Root':
        ku=cert.extensions.get_extension_for_class(x509.KeyUsage)
        assert ku.critical and ku.value.digital_signature and ku.value.key_encipherment
    if name!='Device':
        key=serialization.load_pem_private_key(p[name+'PrivateKey'],None)
        assert key.key_size==2048 and key.public_key().public_numbers()==cert.public_key().public_numbers()
    else:
        key=serialization.load_pem_public_key((OUT/'device-public.pem').read_bytes())
        assert key.public_numbers()==cert.public_key().public_numbers()
        assert cert.extensions.get_extension_for_class(x509.SubjectKeyIdentifier).value==x509.SubjectKeyIdentifier.from_public_key(key)
assert uuid.UUID(p['HostID']).version==4 and uuid.UUID(p['SystemBUID']).version==4
assert p['HostID']!=p['SystemBUID']
assert p['HostID']==p['HostID'].upper() and p['SystemBUID']==p['SystemBUID'].upper()
assert set(wire['PairRecord'])=={'RootCertificate','HostCertificate','DeviceCertificate','HostID','SystemBUID'}
assert wire['ProtocolVersion']=='2' and wire['PairingOptions']['ExtendedPairingErrors']
result={'passed':True,'certificates':3,'signatures':'RSA-2048/SHA-256','private_keys_excluded_from_wire':True,'physical_iphone_verified':False}
(OUT/'certificate-validation.json').write_text(json.dumps(result,indent=2))
print(json.dumps(result))
